#!/bin/sh
# WP-X1: are the sky130 flows bit-exact? Three sweeps of flow A1' (14 designs x 6 mapper variants = 84 netlists):
# the reference sweep (3 workers), a SERIAL sweep (1 worker, PYTHONHASHSEED=1, own TMPDIR and output directory) and a
# 6-WAY PARALLEL sweep (PYTHONHASHSEED=7, another TMPDIR); the sha256 of every mapped netlist must be equal across the three.
# Also: the 12 add/mul scored netlists regenerated by score.py must equal WP-X0's data/netlists byte for byte.
# About 3 minutes on this machine.  Usage: ./sky_determinism.sh [WORKDIR]
set -e
cd "$(dirname "$0")"
export PYTHONDONTWRITEBYTECODE=1
W=${1:-/tmp/sky130_det}
mkdir -p "$W/tmp1" "$W/tmp2"
python3.12 sky_gen.py --n 16 > /dev/null
python3.12 sky_a1.py --workers 3 --tag _det_ref --outdir "$W/ref" > /dev/null
TMPDIR="$W/tmp1" PYTHONHASHSEED=1 python3.12 sky_a1.py --workers 1 --tag _det_serial --outdir "$W/serial" > /dev/null
TMPDIR="$W/tmp2" PYTHONHASHSEED=7 python3.12 sky_a1.py --workers 6 --tag _det_par6 --outdir "$W/par6" > /dev/null
python3.12 - <<'PY'
import json
g = lambda t: {(r["name"], r["variant"]): r["netlist_sha256"] for r in json.load(open(f"data/sky130/a1_N16{t}.json"))["rows"]}
ref = g("_det_ref")
res = {"netlists": len(ref)}
for t in ("_det_serial", "_det_par6"):
    res["identical" + t] = sum(ref[k] == v for k, v in g(t).items())
json.dump(res, open("data/sky130/determinism.json", "w"), indent=1)
print(res)
PY
rm -f data/sky130/a1_N16_det_*.json
for p in add_ripple add_sklansky add_kogge add_cmpcarry add_yosys mul_array mul_tree mul_wallace mul_tree_h mul_dadda_rc mul_dadda_ks mul_yosys; do
  cmp -s .cache/sky130/netlists/${p}_N16.v data/netlists/${p}_N16.v && echo "scored netlist $p: identical to WP-X0's" || echo "scored netlist $p: DIFFERS"
done
